TASK SPECIFICATIONS:
{
  "id": "PUB014",
  "title": "IPv4 Parsing with Format and Range Checks",
  "difficulty": "medium",
  "requirements": "# IPv4 Parsing with Format and Range Checks\n\n- **Difficulty:** Medium (medium)\n\n## Requirements\n\nDesign a PLC function block in Structured Text (ST) that parses a dotted-decimal IPv4 string into a 32-bit unsigned integer.\n\n1. ipText must contain four nonempty decimal-digit segments separated by periods. Each segment must have a value from 0 through 255.\n2. Assemble the address in network byte order: the first segment occupies the most significant 8 bits and the fourth occupies the least significant 8 bits. Write the result to ipValue.\n3. Set ipValue to 0 for malformed input, a nondigit segment, an incorrect segment count or any out-of-range segment. The valid address 0.0.0.0 also produces 0.\n\n## Interface Definition\n\n| Direction | Variable/Field | Data Type | Description |\n| --- | --- | --- | --- |\n| Input | `ipText` | `STRING(254)` | IPv4 text to parse, with a capacity of 254 characters. A valid dotted-decimal address requires at most 15 characters. |\n| Output | `ipValue` | `UDINT` | 32-bit address in network byte order; zero for invalid input. |",
  "scenario": "Strict decimal IPv4 parsing into a network-order unsigned address.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "ipText",
      "type": "STRING(254)",
      "description": "IPv4 text to parse, with a capacity of 254 characters. A valid dotted-decimal address requires at most 15 characters."
    },
    {
      "direction": "OUTPUT",
      "name": "ipValue",
      "type": "UDINT",
      "description": "32-bit address in network byte order; zero for invalid input."
    }
  ],
  "initial_conditions": {
    "ipValue": 0
  },
  "scan_semantics": "Inputs I[k] are sampled at invocation; outputs O[k] are observed after the call. Retained pre-state q[k] becomes q[k+1]. Each test resets the instance. A transition affects the same observed scan. dt_ms is elapsed time since the preceding invocation; the first invocation starts IEC timers at elapsed zero. CycleTime inputs, where supplied, are attributed to the current invocation rather than inferred from dt_ms.",
  "safety_priority": [
    "Malformed or out-of-range data forces zero in the same invocation."
  ],
  "assumptions": [
    "Leading zeros are allowed because the official text requires decimal-digit segments without prohibiting them.",
    "Signs, whitespace, hexadecimal notation and embedded nondigits are rejected.",
    "Input STRING capacity (<=254 UTF-8 bytes) is checked before truncating at the first NUL byte. Embedded NUL terminates the visible IPv4 text; arbitrary leading zeros are permitted within capacity, and each digit character must be ASCII '0'..'9'.",
    "The task interface, requirements, assumptions, and normalized LTL definitions (excluding reference-only ground truth) are supplied identically to both frameworks. Output names always denote observed candidate outputs, never precomputed expected values.",
    "The task interface, requirements, assumptions, and normalized LTL definitions (excluding reference-only ground truth) are supplied identically to both frameworks. Output names always denote observed candidate outputs, never precomputed expected values."
  ],
  "atomic_propositions": {
    "valid": "exactly four nonempty decimal-digit segments separated by periods, each parsed value 0..255",
    "packed": "ipValue=a*16777216+b*65536+c*256+d for the four parsed octets",
    "zero": "ipValue=0",
    "same_input": "k>=1 AND I[k].ipText=I[k-1].ipText",
    "same_output": "k>=1 AND O[k].ipValue=O[k-1].ipValue",
    "ipText": "I[k].ipText: sampled input (STRING(254)).",
    "ipValue": "O[k].ipValue: independently observed post-scan candidate value (UDINT); never defined as expected output.",
    "init": "At the separate pre-invocation initial observation before scan k=0: O_init.ipValue=0."
  },
  "ltl": [
    {
      "id": "PUB014.P_init",
      "kind": "safety",
      "formula": "init",
      "description": "Before the first scan invocation, all declared OUTPUT variables and initial instance state hold their declared initial values.",
      "explanation": "Applies strictly to the fresh pre-invocation initial instance observation before scan k=0 (INITIAL_INSTANCE scope).",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "INITIAL_INSTANCE"
    },
    {
      "id": "PUB014.P1",
      "name": "Valid assembly",
      "formula": "G(valid -> packed)",
      "explanation": "The first octet is the most significant byte.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    },
    {
      "id": "PUB014.P2",
      "name": "Invalid input",
      "formula": "G(!valid -> zero)",
      "explanation": "Invalid data never preserves an old result.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    },
    {
      "id": "PUB014.P3",
      "name": "Stateless parsing",
      "formula": "G(same_input -> same_output)",
      "explanation": "Repeated strings produce repeated results.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    }
  ]
}

ARCHITECTURAL PLAN:
{
  "state_machine": [
    {
      "name": "IDLE",
      "description": "Fresh invocation point. Output is forced to zero until parsing proves a valid IPv4 string in this invocation.",
      "transitions": [
        "IDLE -> SEG_START on invocation start; reset parse accumulators and set valid := false",
        "IDLE -> INVALID if visible string length is zero or NUL is not found within STRING capacity"
      ]
    },
    {
      "name": "SEG_START",
      "description": "Beginning of a decimal segment. The segment must be nonempty.",
      "transitions": [
        "SEG_START -> SEG_DIGITS on ASCII character '0'..'9'",
        "SEG_START -> INVALID on '.', NUL, whitespace, sign, or any nondigit"
      ]
    },
    {
      "name": "SEG_DIGITS",
      "description": "Accumulate decimal digits for the current octet; leading zeros are allowed. Any accumulated value >255 is invalid.",
      "transitions": [
        "SEG_DIGITS -> SEG_DIGITS on ASCII digit if currentValue <=255",
        "SEG_DIGITS -> INVALID on ASCII digit if currentValue >255",
        "SEG_DIGITS -> AFTER_PERIOD on '.' when digitSeen, currentValue <=255, and segmentCount < 3",
        "SEG_DIGITS -> COMPLETE on NUL when digitSeen, currentValue <=255, and segmentCount = 3",
        "SEG_DIGITS -> INVALID on NUL before four segments, extra period, empty segment, or nondigit"
      ]
    },
    {
      "name": "AFTER_PERIOD",
      "description": "A period has completed a segment; the next character must begin the next nonempty segment.",
      "transitions": [
        "AFTER_PERIOD -> SEG_DIGITS on ASCII digit",
        "AFTER_PERIOD -> INVALID on '.', NUL, whitespace, sign, or nondigit"
      ]
    },
    {
      "name": "COMPLETE",
      "description": "Exactly four nonempty decimal segments have been parsed, each 0..255. Pack octets in network byte order.",
      "transitions": [
        "COMPLETE -> DONE after computing ((oct0*256 + oct1)*256 + oct2)*256 + oct3"
      ]
    },
    {
      "name": "INVALID",
      "description": "Malformed text, nondigit segment, wrong segment count, capacity issue, or out-of-range segment. Pending output is zero.",
      "transitions": [
        "INVALID -> DONE with ipValue := 0"
      ]
    },
    {
      "name": "DONE",
      "description": "End of the current invocation. No parse state is retained for the next scan; the next invocation restarts at IDLE.",
      "transitions": [
        "DONE -> IDLE on next invocation"
      ]
    }
  ],
  "timer_plan": {
    "timers": [],
    "pt_durations": [],
    "reset_conditions": "No timers. Parsing is combinational within one invocation and has no timed state.",
    "notes": "No TON, TOF, or TP function blocks are used. Stage 3 contains no timer calls."
  },
  "priorities": [
    "Safety first: check STRING capacity and visible NUL-terminated text before truncation; reject any nondigit, sign, whitespace, hexadecimal, embedded nondigit, empty segment, wrong segment count, or segment value >255.",
    "Any invalid condition forces ipValue := 0 in the same invocation. A previous nonzero ipValue must never be preserved.",
    "Valid input packs octets in network byte order: first segment is the most significant byte and fourth segment is the least significant byte.",
    "Leading zeros are allowed within STRING capacity. The valid address 0.0.0.0 and all invalid inputs both produce ipValue = 0.",
    "Parsing is deterministic and stateless with respect to inputs: identical ipText across invocations produces identical ipValue.",
    "Validate all data before writing the final output; the unified output stage is the only writer of ipValue."
  ],
  "initial_values": {
    "ipValue": 0,
    "state": "IDLE",
    "valid": false,
    "visibleLen": 0,
    "charIndex": 0,
    "segmentCount": 0,
    "currentValue": 0,
    "digitSeen": false,
    "octets": [
      0,
      0,
      0,
      0
    ],
    "pendingValue": 0
  },
  "scan_execution_order": [
    {
      "stage": 1,
      "name": "edge sampling",
      "actions": [
        "Sample ipText once at invocation into a local current-text buffer.",
        "Determine visible length up to the first NUL and verify it is within STRING(254) capacity before truncating.",
        "Optional previous-text copy may be maintained only for diagnostics; no output decision may depend on previous scan state."
      ]
    },
    {
      "stage": 2,
      "name": "safety/reset priority and state transitions",
      "actions": [
        "Reset parse accumulators: visibleLen, charIndex, segmentCount, currentValue, digitSeen, valid, octets, pendingValue.",
        "Run the state machine: capacity/NUL check, four nonempty decimal-digit segments, each 0..255, exact segment count, and no invalid characters.",
        "Safety priority: on any violation set valid := false and pendingValue := 0 immediately.",
        "On valid input, finalize four octets and compute pendingValue := first*16777216 + second*65536 + third*256 + fourth."
      ]
    },
    {
      "stage": 3,
      "name": "unconditional top-level timer FB calls outside CASE/IF",
      "actions": [
        "No timer function blocks are required or called.",
        "This stage is intentionally empty; no timer can affect parsing or output."
      ]
    },
    {
      "stage": 4,
      "name": "unified output assignments",
      "actions": [
        "Single assignment point: ipValue := pendingValue when valid is true; otherwise ipValue := 0.",
        "Because pendingValue is already zeroed for invalid input, ipValue := pendingValue is also safe, but the safety form is explicit.",
        "No other stage writes ipValue."
      ]
    }
  ],
  "formal_assertions": [
    {
      "id": "A1",
      "formula": "G(valid(ipText) -> ipValue = pack(ipText))"
    },
    {
      "id": "A2",
      "formula": "G(!valid(ipText) -> ipValue = 0)"
    },
    {
      "id": "A3",
      "formula": "G((ipValue = 0) -> (!valid(ipText) OR pack(ipText) = 0))"
    }
  ]
}

CODESYS DIALECT CARDS:
[
  {
    "id": "string_parsing",
    "title": "IEC 61131-3 String Manipulation and Parsing",
    "body": "// IEC string operations: FIND, MID, LEFT, RIGHT, LEN, STRING(n)\nVAR\n    s : STRING(80);\n    pos, length : INT;\n    sub : STRING(20);\nEND_VAR\nlength := LEN(s);\npos := FIND(s, '.'); // 1-based index; returns 0 if not found\nIF pos > 1 THEN\n    sub := LEFT(s, pos - 1); // extracts prefix\nEND_IF;"
  },
  {
    "id": "ton_timer",
    "title": "Standard IEC TON Timer Block Invocation",
    "body": "// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!\nVAR\n    timer : TON;\n    runTimer : BOOL;\nEND_VAR\n// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):\nrunTimer := (state = 1) AND NOT resetCmd;\ntimer(IN := runTimer, PT := T#2s);\nIF timer.Q THEN\n    // Timer expired; timer.ET holds elapsed time\nEND_IF;"
  }
]
